"""Throwaway repositories for the tests of the version bump judge.

Each one holds a realistic Cargo.toml, both lockfiles, debian/changelog and a
docs page at version OLD, committed as `base`, then one change committed as
`head`. test_fuzz_targets.py uses them too.
"""

import os
import re
import shutil
import subprocess
import sys
import tempfile

SCRIPT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "is_version_bump.py")
JUDGE = ".github/scripts/version_bump/is_version_bump.py"

GIT_ENV = {
    "GIT_CONFIG_NOSYSTEM": "1",
    "GIT_CONFIG_GLOBAL": os.devnull,
    "GIT_TERMINAL_PROMPT": "0",
    "GIT_AUTHOR_NAME": "t",
    "GIT_AUTHOR_EMAIL": "t@example.invalid",
    "GIT_COMMITTER_NAME": "t",
    "GIT_COMMITTER_EMAIL": "t@example.invalid",
}

MANIFEST = """[package]
name = "epistle"
version = "{v}"
edition = "2024"
rust-version = "1.98"

[dependencies]
serde = {{ version = "1.0.200", features = ["derive"] }}
clap = "4"
"""

LOCK = """# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "clap"
version = "4.5.0"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "1111111111111111111111111111111111111111111111111111111111111111"

[[package]]
name = "epistle"
version = "{v}"
dependencies = [
 "clap",
]
"""

FUZZ_LOCK = """# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "epistle"
version = "{v}"

[[package]]
name = "epistle-fuzz"
version = "0.0.0"
dependencies = [
 "epistle",
]
"""

CHANGELOG = """epistle ({v}) unstable; urgency=medium

  * The previous release.

 -- Glyndor <packages@example.invalid>  Mon, 01 Jan 2026 00:00:00 +0000

epistle (0.12.4) unstable; urgency=medium

  * The one before.

 -- Glyndor <packages@example.invalid>  Mon, 01 Dec 2025 00:00:00 +0000
"""

DOC = """# Container

Run it:

    podman run ghcr.io/glyndor/epistle:{v}

The minor tag `ghcr.io/glyndor/epistle:0.12` keeps getting patches.
"""

OLD = "0.12.5"
NEW = "0.12.6"


def write(path, text):
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with open(path, "w", encoding="utf-8") as handle:
        handle.write(text)


def read(path):
    with open(path, encoding="utf-8") as handle:
        return handle.read()


def sub(path, pattern, replacement, count=0):
    text = read(path)
    changed = re.sub(pattern, replacement, text, count=count, flags=re.M)
    assert changed != text, f"{pattern!r} matched nothing in {path}"
    write(path, changed)


def seed(version=OLD, judge=False):
    write("Cargo.toml", MANIFEST.format(v=version))
    write("Cargo.lock", LOCK.format(v=version))
    write("fuzz/Cargo.lock", FUZZ_LOCK.format(v=version))
    write("debian/changelog", CHANGELOG.format(v=version))
    write("docs/operations/container.md", DOC.format(v=version))
    write("src/main.rs", "fn main() {}\n")
    if judge:
        os.makedirs(os.path.dirname(JUDGE))
        shutil.copy(SCRIPT, JUDGE)


def pkg_version(path, version):
    sub(path, r'^(name = "epistle"\n)version = ".*"$', rf'\1version = "{version}"')


def new_entry(version=NEW):
    entry = (
        f"epistle ({version}) unstable; urgency=medium\n\n  * A change.\n\n"
        " -- Glyndor <packages@example.invalid>  Mon, 01 Feb 2026 00:00:00 +0000\n\n"
    )
    write("debian/changelog", entry + read("debian/changelog"))


def bump_doc():
    write("docs/operations/container.md", read("docs/operations/container.md").replace(OLD, NEW))


def bump_toml():
    sub("Cargo.toml", rf'^version = "{OLD}"$', f'version = "{NEW}"', count=1)


def bump_all():
    bump_toml()
    pkg_version("Cargo.lock", NEW)
    pkg_version("fuzz/Cargo.lock", NEW)
    new_entry()
    bump_doc()


class Repo:
    """A throwaway repository with a `base` and a `head` tag."""

    def __init__(self, change, **seed_args):
        self.dir = tempfile.mkdtemp()
        here = os.getcwd()
        os.chdir(self.dir)
        try:
            self.git("init", "-q", ".")
            self.git("config", "commit.gpgsign", "false")
            seed(**seed_args)
            self.commit("base")
            change()
            self.commit("head")
        finally:
            os.chdir(here)

    def git(self, *args):
        env = {**os.environ, **GIT_ENV}
        subprocess.run(["git", *args], cwd=self.dir, env=env, check=True, capture_output=True)

    def commit(self, tag):
        self.git("add", "-A")
        self.git("commit", "-q", "--allow-empty", "-m", tag)
        self.git("tag", tag)

    def run(self, base="base", head="head", script=SCRIPT):
        env = {**os.environ, **GIT_ENV}
        return subprocess.run(
            [sys.executable, "-I", script, base, head],
            cwd=self.dir,
            env=env,
            capture_output=True,
            text=True,
            check=False,
        )

    def close(self):
        shutil.rmtree(self.dir, ignore_errors=True)
